  if (!strcmp(compname, "PG1Xtal")) return 12;
  if (!strcmp(compname, "Mono_Out")) return 13;
  if (!strcmp(compname, "SC2")) return 14;
  if (!strcmp(compname, "before_sample")) return 15;
  if (!strcmp(compname, "Sample_Cradle_2")) return 16;
